export function coverSpec({trimWidth,trimHeight,pageCount=0,paperThicknessIn=.002252,bleed=.125,binding='paperback',hinge=.375,dpi=300}){trimWidth=Number(trimWidth);trimHeight=Number(trimHeight);pageCount=Math.max(0,Number(pageCount)||0);const spine=pageCount*Number(paperThicknessIn||.002252),joint=binding==='hardcover'?Number(hinge||.375):0,totalWidth=2*trimWidth+spine+2*Number(bleed)+2*joint,totalHeight=trimHeight+2*Number(bleed);return {trimWidth,trimHeight,pageCount,spineWidthIn:spine,bleedIn:Number(bleed),jointIn:joint,totalWidthIn:totalWidth,totalHeightIn:totalHeight,dpi:Number(dpi)||300,pixels:{width:Math.round(totalWidth*dpi),height:Math.round(totalHeight*dpi)},safeGuides:{backCoverEnd:Number(bleed)+trimWidth,spineStart:Number(bleed)+trimWidth+joint,spineEnd:Number(bleed)+trimWidth+joint+spine,frontCoverStart:Number(bleed)+trimWidth+2*joint+spine}};}
export function normalizePageSettings(data={}){return {marginTop:Number(data.marginTop??.75),marginBottom:Number(data.marginBottom??.75),marginInside:Number(data.marginInside??.875),marginOutside:Number(data.marginOutside??.625),gutter:Number(data.gutter??.125),pageNumbers:data.pageNumbers!==false,runningHeaders:data.runningHeaders!==false,chapterOpenStyle:data.chapterOpenStyle||'drop',pageColor:data.pageColor||'#fffdf8',pageTexture:data.pageTexture||'paper',fontFamily:data.fontFamily||'serif',fontSize:Number(data.fontSize||11),lineHeight:Number(data.lineHeight||1.3)};}
export function chapterManifest(chapters=[]){return chapters.map((c,i)=>({id:c.id||`chapter-${i+1}`,order:i+1,title:c.title||`Chapter ${i+1}`,file:`chapters/${String(i+1).padStart(3,'0')}-${slug(c.title||`chapter-${i+1}`)}.json`,wordCount:String(c.text||c.content||'').trim().split(/\s+/).filter(Boolean).length}));}
const slug=s=>String(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||'chapter';
